+func (dl *datalog) writeRecords(records [][]byte, rts []recordType) ([]uint16, []uint32, error) {
+	if len(records) != len(rts) {
+		return nil, nil, errors.New("records and rts length mismatch")
+	}
+	
+	// Preallocate slices for return values
+	segmentIDs := make([]uint16, len(records))
+	offsets := make([]uint32, len(records))
+	
+	// Collect records to write in batches per segment
+	type batchEntry struct {
+		data []byte
+		rt   recordType
+		idx  int // index in the original records slice
+	}
+	
+	batches := make(map[uint16][]batchEntry) // segmentID -> entries
+	batchSizes := make(map[uint16]int64)     // segmentID -> total size
+	
+	// First pass: organize records into batches by segment
+	for i, data := range records {
+		segmentID := dl.curSeg.id
+		
+		// Check if current segment would be full after adding this record
+		if dl.curSeg.meta.Full || dl.curSeg.size+batchSizes[segmentID]+int64(len(data)) > int64(dl.opts.maxSegmentSize) {
+			// Current segment is full, create a new one
+			dl.curSeg.meta.Full = true
+			if err := dl.swapSegment(); err != nil {
+				return nil, nil, err
+			}
+			segmentID = dl.curSeg.id
+		}
+		
+		// Add to batch for this segment
+		batches[segmentID] = append(batches[segmentID], batchEntry{data: data, rt: rts[i], idx: i})
+		batchSizes[segmentID] += int64(len(data))
+	}
+	
+	// Second pass: write batches to their respective segments
+	for segmentID, batch := range batches {
+		segment := dl.segments[segmentID]
+		if segment == nil {
+			// This shouldn't happen, but let's be safe
+			return nil, nil, errors.New("segment not found")
+		}
+		
+		// Prepare data for batch write
+		totalSize := int64(0)
+		for _, entry := range batch {
+			totalSize += int64(len(entry.data))
+		}
+		
+		batchData := make([]byte, totalSize)
+		offset := int64(0)
+		recordOffsets := make([]int64, len(batch))
+		
+		// Copy all record data into one buffer
+		for i, entry := range batch {
+			recordOffsets[i] = offset
+			copy(batchData[offset:], entry.data)
+			offset += int64(len(entry.data))
+		}
+		
+		// Write the entire batch at once
+		startOff := segment.size
+		if _, err := segment.WriteAt(batchData, startOff); err != nil {
+			return nil, nil, err
+		}
+		
+		// Update segment metadata for each record
+		for i, entry := range batch {
+			recordOffset := uint32(startOff + recordOffsets[i])
+			
+			// Update metrics
+			switch entry.rt {
+			case recordTypePut:
+				segment.meta.PutRecords++
+			case recordTypeDelete:
+				segment.meta.DeleteRecords++
+			}
+			
+			// Store return values
+			segmentIDs[entry.idx] = segmentID
+			offsets[entry.idx] = recordOffset
+		}
+		
+		// Update segment size
+		segment.size += totalSize
+	}
+	
+	return segmentIDs, offsets, nil
+}
