+// promoteRecords writes multiple records to the current segment in batch.
+func (db *DB) promoteRecords(recs []record) error {
+	if len(recs) == 0 {
+		return nil
+	}
+	
+	// Prepare data for batch write
+	data := make([][]byte, len(recs))
+	rts := make([]recordType, len(recs))
+	
+	for i, rec := range recs {
+		data[i] = rec.data
+		rts[i] = rec.rtype
+	}
+	
+	// Write records in batch
+	segmentIDs, offsets, err := db.datalog.writeRecords(data, rts)
+	if err != nil {
+		return err
+	}
+	
+	// Update index for each record
+	db.mu.Lock()
+	defer db.mu.Unlock()
+	
+	for i, rec := range recs {
+		// Find the slot in the index that points to this record
+		h := hash.Hash(rec.key(), db.hashSeed)
+		bucketIdx := h % numBuckets
+		b := &db.index.buckets[bucketIdx]
+		
+		// Lock the bucket for modification
+		b.mu.Lock()
+		
+		// Find the exact slot
+		for j := 0; j < slotsPerBucket; j++ {
+			sl := b.slots[j]
+			
+			// No more slots in the bucket
+			if sl.offset == 0 {
+				break
+			}
+			
+			// Slot points to this record
+			if h == sl.hash && rec.offset == sl.offset && rec.segmentID == sl.segmentID {
+				// Update index
+				b.slots[j].segmentID = segmentIDs[i]
+				b.slots[j].offset = offsets[i]
+				b.mu.Unlock()
+				
+				// Write updated bucket to disk
+				if err := b.write(); err != nil {
+					return err
+				}
+				break
+			}
+		}
+		
+		// Note: If we don't find the slot, it means the record is no longer in the index,
+		// which can happen if it was deleted or overwritten between the compaction decision
+		// and the actual compaction. This is fine and we just skip updating the index.
+	}
+	
+	return nil
+}
+
+// CompactionResult holds the compaction result.
+type CompactionResult struct {
+	CompactedSegments int
+	ReclaimedRecords  int
+	ReclaimedBytes    int
+}
+
+func (db *DB) compact(sourceSeg *segment) (CompactionResult, error) {
+	cr := CompactionResult{}
+
+	db.mu.Lock()
+	sourceSeg.meta.Full = true // Prevent writes to the compacted file.
+	db.mu.Unlock()
+
+	it, err := newSegmentIterator(sourceSeg)
+	if err != nil {
+		return cr, err
+	}
+	
+	// Batch processing: collect records and promote them in batches
+	const batchSize = 100
+	var batch []record
+	
+	// Copy records from sourceSeg to the current segment.
+	for {
+		err := func() error {
+			db.mu.Lock()
+			defer db.mu.Unlock()
+			rec, err := it.next()
+			if err != nil {
+				return err
+			}
+			if rec.rtype == recordTypeDelete {
+				cr.ReclaimedRecords++
+				cr.ReclaimedBytes += len(rec.data)
+				return nil
+			}
+			
+			// Add record to batch
+			batch = append(batch, rec)
+			
+			// If batch is full, promote all records in batch
+			if len(batch) >= batchSize {
+				if err := db.promoteRecords(batch); err != nil {
+					return err
+				}
+				// Clear batch
+				batch = batch[:0]
+			}
+			
+			return nil
+		}()
+		if err == ErrIterationDone {
+			break
+		}
+		if err != nil {
+			return cr, err
+		}
+	}
+	
+	// Process remaining records in batch
+	if len(batch) > 0 {
+		if err := db.promoteRecords(batch); err != nil {
+			return cr, err
+		}
+	}
+
+	db.mu.Lock()
+	defer db.mu.Unlock()
+	err = db.datalog.removeSegment(sourceSeg)
+	return cr, err
+}
