// writeRecordsBatch writes multiple records to the current segment in a single batch.
// This is a simplified version that writes all records to the same segment.
func (dl *datalog) writeRecordsBatch(records [][]byte, rts []recordType) ([]uint16, []uint32, error) {
	if len(records) != len(rts) {
		return nil, nil, errors.New("records and rts length mismatch")
	}

	if len(records) == 0 {
		return nil, nil, nil
	}

	// Calculate total size needed
	totalSize := int64(0)
	for _, data := range records {
		totalSize += int64(len(data))
	}

	// Check if we need a new segment
	if dl.curSeg.meta.Full || dl.curSeg.size+totalSize > int64(dl.opts.maxSegmentSize) {
		dl.curSeg.meta.Full = true
		if err := dl.swapSegment(); err != nil {
			return nil, nil, err
		}
	}

	// Prepare batch data
	batchData := make([]byte, totalSize)
	offsetsInBatch := make([]int64, len(records))
	currentOffset := int64(0)

	for i, data := range records {
		offsetsInBatch[i] = currentOffset
		copy(batchData[currentOffset:], data)
		currentOffset += int64(len(data))
	}

	// Write the entire batch at once
	startOffset := dl.curSeg.size
	if _, err := dl.curSeg.WriteAt(batchData, startOffset); err != nil {
		return nil, nil, err
	}

	// Update segment metadata and prepare return values
	segmentID := dl.curSeg.id
	returnOffsets := make([]uint32, len(records))

	for i, rt := range rts {
		returnOffsets[i] = uint32(startOffset + offsetsInBatch[i])

		// Update metrics
		switch rt {
		case recordTypePut:
			dl.curSeg.meta.PutRecords++
		case recordTypeDelete:
			dl.curSeg.meta.DeleteRecords++
		}
	}

	// Update segment size
	dl.curSeg.size += totalSize

	return []uint16{segmentID}, returnOffsets, nil
}
